begin;
set local search_path=public,extensions;
select plan(26);

select ok((select count(*)=10 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname=any(array['signature_envelopes','signature_documents','signature_signers','signature_signer_authorities','signature_attempts','signature_provider_events','signature_evidence_packages','signature_certificates','trusted_timestamps','signature_provider_configs'])),'V4.1 signature provider schema is complete');
select ok((select count(*)=10 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['signature_envelopes','signature_documents','signature_signers','signature_signer_authorities','signature_attempts','signature_provider_events','signature_evidence_packages','signature_certificates','trusted_timestamps','signature_provider_configs'])),'RLS is enabled on every signature table');
select ok((select count(*)=6 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['create_signature_envelope','add_signature_signer','authorize_signature_signer','ready_signature_envelope','process_verified_signature_provider_event','run_mock_signature_provider'])),'signature commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['create_signature_envelope','add_signature_signer','authorize_signature_signer','ready_signature_envelope','process_verified_signature_provider_event','run_mock_signature_provider']) and has_function_privilege('anon',p.oid,'EXECUTE')),'anonymous cannot execute signature commands');
select ok((select count(*)=4 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['create_signature_envelope','add_signature_signer','authorize_signature_signer','ready_signature_envelope'])),'authenticated users only receive human signature commands');
select ok((select count(*)=2 and bool_and(has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['process_verified_signature_provider_event','run_mock_signature_provider'])),'verified webhook and development mock are worker-only');
select ok(not has_table_privilege('authenticated','public.signature_envelopes','INSERT') and not has_table_privilege('authenticated','public.signature_signers','UPDATE') and not has_table_privilege('authenticated','public.signature_provider_events','INSERT'),'authenticated cannot bypass signature command APIs');
select ok(not has_table_privilege('authenticated','public.signature_provider_configs','SELECT'),'provider configuration is not exposed to tenant users');
select ok((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname='signature_envelope_access' and p.prosecdef and p.proconfig::text like '%search_path=%'),'tenant access is centralized in a protected predicate');
select ok((select count(*)>=8 from pg_trigger where tgname=any(array['signature_documents_immutable','signature_authorities_immutable','signature_attempts_immutable','signature_events_immutable','signature_evidence_immutable','signature_certificates_immutable','signature_timestamps_immutable','signature_configs_immutable']) and not tgisinternal),'signature evidence and provider history are immutable');
select ok((select count(*)=10 from pg_policies where schemaname='public' and tablename=any(array['signature_envelopes','signature_documents','signature_signers','signature_signer_authorities','signature_attempts','signature_provider_events','signature_evidence_packages','signature_certificates','trusted_timestamps','signature_provider_configs'])),'all signature tables have explicit restrictive read policies');
select ok((select count(*)>=2 from pg_constraint where conrelid='public.signature_envelopes'::regclass and pg_get_constraintdef(oid) like '%SIMPLE%' and pg_get_constraintdef(oid) like '%ADVANCED%' and pg_get_constraintdef(oid) like '%QUALIFIED%'),'signature levels are constrained to honest legal labels');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.signature_envelopes'::regclass and pg_get_constraintdef(oid) like '%READY_FOR_SIGNATURE%' and pg_get_constraintdef(oid) like '%PARTIALLY_SIGNED%' and pg_get_constraintdef(oid) like '%VOIDED%'),'complete V4.1 envelope lifecycle is constrained');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.signature_documents'::regclass and pg_get_constraintdef(oid) like '%contract_version_id%'),'signature document binds the exact immutable contract version');
select ok((select count(*)>=2 from pg_constraint where conrelid='public.signature_documents'::regclass and pg_get_constraintdef(oid) like '%sha256%'),'document and evidence hashes are validated');
select ok((select count(*)=2 from pg_constraint where conrelid='public.signature_provider_events'::regclass and contype='u'),'provider event id and nonce both have anti-replay uniqueness');
select ok((select pg_get_functiondef(p.oid) like '%SIGNATURE_LEVEL_NOT_SUPPORTED%' and pg_get_functiondef(p.oid) like '%QUALIFIED_LEVEL_NOT_ACHIEVED%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='process_verified_signature_provider_event'),'webhook processing never overstates advanced or qualified signatures');
select ok((select pg_get_functiondef(p.oid) like '%SIGNER_AUTHORITY_REQUIRED%' and pg_get_functiondef(p.oid) like '%amount_ceiling_minor%' and pg_get_functiondef(p.oid) like '%revoked_at%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ready_signature_envelope'),'ready transition revalidates legal authority, scope, dates, revocation and ceiling');
select ok((select pg_get_functiondef(p.oid) like '%SIGNATURE_EVENT_REPLAY_MISMATCH%' and pg_get_functiondef(p.oid) like '%replayed%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='process_verified_signature_provider_event'),'provider event replay is idempotent and mismatched replay is rejected');
select ok((select pg_get_functiondef(p.oid) like '%SignatureEnvelopeSignedV1%' and pg_get_functiondef(p.oid) like '%signature.provider_event_processed%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='process_verified_signature_provider_event'),'signature transitions emit Outbox and audit evidence');
select ok((select pg_get_functiondef(p.oid) like '%contract_signatures%' and pg_get_functiondef(p.oid) like '%signature_evidence_packages%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='process_verified_signature_provider_event'),'signed provider events bridge legacy contract signatures and seal the proof package');
select ok((select count(*)=1 from public.signature_provider_configs where provider_code='MATRICIA_DEV_MOCK' and environment='DEVELOPMENT' and status='ACTIVE' and supported_levels=array['SIMPLE']::text[]),'development mock is explicit and cannot claim an unsupported level');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name='signature_provider_configs' and column_name=any(array['secret','secret_value','api_key','access_token','private_key'])),'provider configuration stores references, never secret values');
select ok((select pg_get_functiondef(p.oid) like '%SIGNATURE_CONTRACT_VERSION_STALE%' and pg_get_functiondef(p.oid) like '%supersedes_envelope_id%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_signature_envelope'),'changed content requires a current version and a new envelope');
select ok((select pg_get_functiondef(p.oid) like '%auth.role()%' and pg_get_functiondef(p.oid) like '%service_role%' and pg_get_functiondef(p.oid) like '%signature_verified%' and pg_get_functiondef(p.oid) like '%webhook_tolerance_seconds%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='process_verified_signature_provider_event'),'webhook processing is worker-only, preverified and time bounded');
select ok((select count(*)=2 and bool_and(not p.prosecdef or p.proconfig::text like '%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname=any(array['enforce_signature_signer_level_attestation','enforce_signature_envelope_level_honesty']))and(select count(*)=2 from pg_trigger where tgname=any(array['signature_signer_level_attestation','signature_envelope_level_honesty'])and not tgisinternal),'every signer level is attested and checked before final SIGNED state');

select * from finish();
rollback;
